export function wrapGatewayPersonalToolExecution(
  execute: AnyAgentTool["execute"],
): AnyAgentTool["execute"] {
  return async (...args) =>
    await withGatewayPersonalToolUser(
      readToolStringParam(asNonArrayRecord(args[1]) ?? {}, "user"),
      async () => {
