import {Type} from "typebox";
export {optionalStringEnum,stringEnum} from "./string-enum.js";
type IntegerSchemaOptions = {
  description?: string;
  maximum?: number;
};

function optionalIntegerSchema(minimum: number, options: IntegerSchemaOptions) {
  return Type.Optional(Type.Integer({ minimum, ...options }));
}

/** Builds an optional positive integer schema. */
export function optionalPositiveIntegerSchema(options: IntegerSchemaOptions = {}) {
  return optionalIntegerSchema(1, options);
}

/** Builds an optional non-negative integer schema. */
export function optionalNonNegativeIntegerSchema(options: IntegerSchemaOptions = {}) {
  return optionalIntegerSchema(0, options);
}

import {Type,type Static} from "typebox";
import {closedObject} from "./closed-object.js";
import {NonEmptyString} from "./primitives.js";
import {stringLiteralUnion} from "./string-literal-union.js";
export const AgentActivityItemSchema = closedObject({
  itemId: NonEmptyString,
  phase: stringLiteralUnion(["start", "update", "end"]),
  kind: Type.String(),
  title: Type.String(),
  status: Type.Optional(
    stringLiteralUnion(["running", "completed", "failed", "blocked", "skipped"]),
  ),
  name: Type.Optional(Type.String()),
  meta: Type.Optional(Type.String()),
  commandBearing: Type.Optional(Type.Boolean()),
  toolCallId: Type.Optional(Type.String()),
  // The history page has no matching result; this is not a terminal receipt.
  unpairedCall: Type.Optional(Type.Boolean()),
  startedAt: Type.Optional(Type.Number()),
  endedAt: Type.Optional(Type.Number()),
  error: Type.Optional(Type.String()),
  summary: Type.Optional(Type.String()),
  progressText: Type.Optional(Type.String()),
  suppressChannelProgress: Type.Optional(Type.Boolean()),
  hideFromChannelProgress: Type.Optional(Type.Boolean()),
  approvalId: Type.Optional(Type.String()),
  approvalSlug: Type.Optional(Type.String()),
});
export type AgentActivityItem = Static<typeof AgentActivityItemSchema>;
export const ChatHistoryActivitySchema = closedObject({
  messageId: NonEmptyString,
  items: Type.Array(AgentActivityItemSchema),
});
export type ChatHistoryActivity = Static<typeof ChatHistoryActivitySchema>;

import {Type} from "typebox";
export const CronStreamApprovalEndedSchema = Type.Object(
  {
    code: Type.Literal("CRON_STREAM_APPROVAL_ENDED"),
    saved: Type.Literal(false),
    action: Type.Union([Type.Literal("add"), Type.Literal("update")]),
    approvalId: Type.String({ minLength: 1 }),
    outcome: Type.Union([
      Type.Literal("operator-denied"),
      Type.Literal("expired"),
      Type.Literal("cancelled"),
    ]),
    message: Type.String({ minLength: 1 }),
  },
  { additionalProperties: false },
);
